    duplicate_rows = df[df['patient_id'].duplicated(keep=False)]
    print("Duplicate patient_id entries:")
    print(duplicate_rows[['patient_id', 'sample_seq', 'arm', 'severity', 'age', 'sex']])
else:
    print("No duplicate patient_id entries found.")"}
